import{_ as r,o as a,a as t,b as i}from"./app.C41L12d5.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMT编程","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/ai_core_simt_programming"},{"text":"同步机制","link":"/guide/programming_guide/programming_model/ai_core_simt_programming/synchronization"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simt_programming/synchronization.md","filePath":"guide/programming_guide/programming_model/ai_core_simt_programming/synchronization.md","outlineHeaders":[{"level":2,"title":"接口概览","slug":"接口概览","link":"#接口概览"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1787050286000}'),o={name:"guide/programming_guide/programming_model/ai_core_simt_programming/synchronization.md"};function d(n,e,m,_,l,g){return a(),t("div",null,[...e[0]||(e[0]=[i('<div><article class="markdown-body"><h1>同步机制<span id="ZH-CN_TOPIC_0000002554691683"></span></h1><p>SIMT是一种单指令多线程的编程模型，该编程模型旨在通过多线程并发执行达到隐藏访存延迟，提升计算吞吐量的目的。SIMT编程模型中，一个Thread Block内的多个Thread并行执行，不同Thread的执行进度和内存访问到达顺序可能不同。当线程之间存在数据依赖时，需要使用同步接口或内存栅栏接口约束执行顺序和内存可见性，避免读到未完成写入的数据。同步接口主要分为两类：</p><ul><li><strong>同步屏障（barrier）</strong>：要求同一作用范围内的线程都到达指定位置后，程序才能继续执行。</li><li><strong>内存栅栏（memory fence）</strong>：约束调用线程在栅栏前后的内存访问顺序，使栅栏前的内存操作按指定范围对其他线程可见。内存栅栏不会等待其他线程到达同一位置。</li></ul><h2 id="接口概览">接口概览<a class="header-anchor" href="#接口概览">​</a></h2><table><thead><tr><th>类型</th><th>代表接口</th><th>典型用途</th></tr></thead><tbody><tr><td>同步屏障</td><td><code>asc_syncthreads</code></td><td>Thread Block内阶段同步，例如先写UB，再统一读取。</td></tr><tr><td>内存栅栏</td><td><code>asc_threadfence_block</code>、<code>asc_threadfence</code></td><td>发布数据或标志前，约束当前Thread的内存访问顺序和可见性。</td></tr></tbody></table><p>同步接口和内存栅栏接口的详细语义、作用范围、使用示例及注意事项，请参见<a href="../../../../api/SIMT-API/sync_and_memory_fence/sync_and_memory_fence_intro.html">同步与内存栅栏简介</a>。</p><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>需要Thread Block内所有Thread完成某一阶段后再继续执行时，使用同步屏障。</li><li>只需要保证当前Thread的内存写入顺序和可见性时，使用内存栅栏。</li><li>不要将内存栅栏当作同步屏障使用。内存栅栏不会等待其他Thread，也不保证其他Thread已经执行到同一位置。</li><li>不要将同步屏障当作跨Thread Block同步接口使用。不同Thread Block之间如需共享状态，应结合Global Memory、原子操作和内存栅栏设计同步协议。</li><li>多个Thread并发写同一地址时，同步屏障和内存栅栏都不能替代原子操作；需要避免写冲突，可使用<a href="atomic_operations.html">原子操作</a>保证读改写过程的原子性。</li></ul></article></div>',1)])])}const h=r(o,[["render",d]]);export{s as __pageData,h as default};
